"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9167],{61981:n=>{n.exports=JSON.parse('{"functions":[{"name":"method_scope","desc":"Method call and nested name.\\n\\n**Syntax:** `obj::Method(args);` \xb7 `obj::Child` (no call) \xb7 `Class::Method` (definition)\\n\\n**Emit:** `obj:Method(args)` / `obj.Child`\\n\\n```clpp\\nplayers::PlayerAdded::Connect(fn);\\nplayer::FindFirstChild(\\"x\\");\\n```\\n\\nDatatype / `task::wait` emit `.` (not Instance methods).","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":37,"path":"moonwave/Operators.lua"}},{"name":"table_key","desc":"Dictionary / module table key. Not a method call.\\n\\n**Syntax:** `Table:Key`\\n\\n**Emit:** `Table.Key`\\n\\n```clpp\\nDataService:Server::WaitFor(p);\\npost(stats:Coins);\\n```\\n\\nRange-for uses `:` in a different position: `for (T x : list)`.","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":56,"path":"moonwave/Operators.lua"}},{"name":"property","desc":"Instance or value property.\\n\\n**Syntax:** `instance.Property`\\n\\n**Emit:** `instance.Property`\\n\\n```clpp\\nplayer.Name = \\"Kartz\\";\\n```","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":72,"path":"moonwave/Operators.lua"}},{"name":"concat","desc":"String concatenation. Never `+` or Lua `..`.\\n\\n**Syntax:** `a .: b .: c`\\n\\n**Emit:** `a .. b` (left-associative)\\n\\n```clpp\\nreturn player.Name .: \\"_LeaderstatsJanitor\\";\\n```","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":88,"path":"moonwave/Operators.lua"}},{"name":"janitor_connect","desc":"Subscribe and give the connection to Janitor. `~>Connect` and `~>Once` only.\\n\\n**Syntax:** `signal~>Connect(fn);` \xb7 `signal~>Once(fn);`\\n\\n**Emit:** `janitor:Add(signal:Connect(fn), \\"Disconnect\\")`\\n\\nLooks up `janitor` local, `self.janitor`, or synthetic `__janitor`.","params":[{"name":"fn","desc":"Listener","lua_type":"func"}],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":103,"path":"moonwave/Operators.lua"}},{"name":"arithmetic","desc":"Numeric arithmetic. `+` does not concatenate. `*` is never pointer deref.\\n\\n**Syntax:** `a + b - c * d / e`\\n\\n**Emit:** same operators","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":115,"path":"moonwave/Operators.lua"}},{"name":"comparison","desc":"`!=` emits `~=`. The others stay the same.\\n\\n**Syntax:** `a != b` \xb7 `a == b`\\n\\n**Emit:** `~=` / `==` / `<` / `>` / `<=` / `>=`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":127,"path":"moonwave/Operators.lua"}},{"name":"logic","desc":"Boolean logic.\\n\\n**Syntax:** `a && b || !c`\\n\\n**Emit:** `and` / `or` / `not`\\n\\nNo ternary `? :`.","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":141,"path":"moonwave/Operators.lua"}},{"name":"assignment","desc":"Assignment and compound assignment.\\n\\n**Syntax:** `name = value;` \xb7 `name += 1;`\\n\\n**Emit:** `=` `+=` `-=` `*=` `/=`\\n\\nObservable assignment writes `.Value`.","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":155,"path":"moonwave/Operators.lua"}},{"name":"increment","desc":"Always emits `+= 1` / `-= 1`. Prefix/postfix value is not preserved.\\n\\n**Syntax:** `i++;` \xb7 `i--;`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":165,"path":"moonwave/Operators.lua"}},{"name":"designated","desc":"C++ designated initializer \u2192 Luau table field.\\n\\n**Syntax:** `Type { .Field = value }`\\n\\n**Emit:** `{ Field = value }`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":177,"path":"moonwave/Operators.lua"}}],"properties":[],"types":[],"name":"Operators","desc":"CL++ does **not** use `->`. Four accessors cover Roblox, plus janitor `~>` and C-like arithmetic.\\n\\n| Operator | Meaning | Luau |\\n| --- | --- | --- |\\n| `::` | method / scope | `:` on a call, `.` otherwise |\\n| `:` | table / dictionary key | `.` |\\n| `.` | Instance or value property | `.` |\\n| `.:` | string concatenation | `..` |\\n| `~>` | Connect / Once with Janitor | `janitor:Add(..., \\"Disconnect\\")` |\\n\\n`+` only adds numbers. `!=` `&&` `||` `!` emit `~=` `and` `or` `not`. `++` / `--` emit `+= 1` / `-= 1`.\\n\\nFull pages: [Language reference \u2014 Operators](/CLPP/docs/reference).","source":{"line":19,"path":"moonwave/Operators.lua"}}')}}]);